// Code node "Verify event" (run once for all items).
//
// The Webhook node has already checked the HS256 signature and expiry of the dispatcher's
// token (JWT auth credential). This node checks what it cannot: issuer and audience, that
// the token was issued for exactly this payload (its SHA-256 is a signed claim) and for this
// event id, and that the envelope is well formed. A captured token is useless with any
// other body and expires within minutes.
const crypto = require('crypto');

const WEBHOOK_NODE = 'Follow-up event webhook';
const EVENT_TYPES = ["follow_up.approved"];
const ISSUER = 'lead-automation-dispatcher';
const AUDIENCE = 'n8n';
const MAX_PAYLOAD_CHARS = 65536;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

const request = $(WEBHOOK_NODE).first().json;
const claims = request.jwtPayload || {};
const raw = request.body ? request.body.payload : undefined;

function reject(reason) {
  return [{ json: { valid: false, reason } }];
}

if (typeof raw !== 'string' || raw.length === 0) {
  return reject('body.payload must be a non-empty JSON string');
}
if (raw.length > MAX_PAYLOAD_CHARS) {
  return reject('payload is too large');
}
if (claims.iss !== ISSUER || claims.aud !== AUDIENCE) {
  return reject('unexpected token issuer or audience');
}
const digest = crypto.createHash('sha256').update(raw, 'utf8').digest('hex');
if (digest !== claims.payload_sha256) {
  return reject('the payload does not match the token');
}
let event;
try {
  event = JSON.parse(raw);
} catch (error) {
  return reject('the payload is not valid JSON');
}
if (!UUID.test(String(event.event_id)) || event.event_id !== claims.eid) {
  return reject('the payload is for another event');
}
if (!EVENT_TYPES.includes(event.event_type)) {
  return reject(`unsupported event type ${event.event_type}`);
}
if (!UUID.test(String(event.lead_id))) {
  return reject('lead_id is missing or invalid');
}
const data = event.data && typeof event.data === 'object' ? event.data : {};
if (data.draft_id !== undefined && !UUID.test(String(data.draft_id))) {
  return reject('draft_id is invalid');
}
return [
  {
    json: {
      valid: true,
      event_id: event.event_id,
      event_type: event.event_type,
      lead_id: event.lead_id,
      correlation_id: String(event.correlation_id || '').slice(0, 64),
      attempt: Number(event.attempt) || 1,
      data,
      started_at: Date.now(),
    },
  },
];

// Code node "Plan <step> retry" (run once for all items), placed after an HTTP Request node
// that returns the full response and never throws on HTTP errors.
//
// Classifies the API's answer and decides what happens next:
//   ok          2xx: continue with the step the API names in body.next
//   retry       transient (connection error, 429, 5xx): wait, then call again
//   exhausted   transient, but the attempts for this run are used up: stop this run with an
//               error so the event is delivered again later (the dispatcher backs off)
//   permanent   4xx: stop; an operator must act (nothing is retried automatically)
//
// The wait grows exponentially with full jitter and honours Retry-After, capped at 60 s.
const STEP = 'deliver';
const MAX_ATTEMPTS = 3;
const BASE_WAIT_S = 10;

const response = $json || {};
const status = Number(response.statusCode || 0);
const body = response.body && typeof response.body === 'object' ? response.body : {};
const attempt = $runIndex + 1;

let route;
if (status >= 200 && status < 300) {
  route = 'ok';
} else if (status === 0 || status === 429 || status >= 500) {
  route = attempt < MAX_ATTEMPTS ? 'retry' : 'exhausted';
} else {
  route = 'permanent';
}

let waitS = 0;
if (route === 'retry') {
  const headers = response.headers || {};
  const retryAfter = Number(headers['retry-after'] || 0);
  const ceiling = Math.min(60, BASE_WAIT_S * 2 ** (attempt - 1));
  const jittered = Math.max(1, Math.round(ceiling / 2 + Math.random() * (ceiling / 2)));
  waitS = Math.min(60, Math.max(jittered, retryAfter));
}

const error = body.error || {};
return [
  {
    json: {
      step: STEP,
      route,
      attempt,
      status_code: status,
      wait_s: waitS,
      next: route === 'ok' ? String(body.next || 'stop') : 'stop',
      lead_status: body.status || null,
      detail: body.detail || {},
      error: route === 'ok' ? null : String(error.code || (response.error && response.error.message) || `HTTP ${status}`).slice(0, 200),
    },
  },
];

// Code node "Summarize run" (run once for all items): what to report for this execution.
//
//   success   the pipeline ran to its end (a draft exists, or a delivery was made)
//   stopped   the run ended on purpose: the lead needs review, or a permanent error needs
//             an operator; the event is complete and is not delivered again
//   error     a transient failure outlasted this run's retries; the API schedules another
//             delivery of the event with backoff
const STAGES = ["Plan delivery retry"]; // plan nodes, latest stage first
const VERIFY_NODE = 'Verify event';

const verified = $(VERIFY_NODE).first().json;
let last = null;
for (const name of STAGES) {
  if ($(name).isExecuted) {
    last = $(name).last().json;
    break;
  }
}

let status;
let step;
let error = null;
if (last === null) {
  status = 'stopped';
  step = 'next_step';
} else {
  step = last.step;
  if (last.route === 'ok') {
    status = last.next === 'done' ? 'success' : 'stopped';
  } else if (last.route === 'permanent') {
    status = 'stopped';
    error = last.error;
  } else {
    status = 'error';
    error = last.error;
  }
}

return [
  {
    json: {
      event_id: verified.event_id,
      report: {
        execution_id: String($execution.id),
        status,
        step,
        duration_ms: Math.max(0, Date.now() - Number(verified.started_at || Date.now())),
        error,
      },
    },
  },
];
